using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using DotReticulum.Applications.Rnid;
using DotReticulum.Applications.Rngit;
using DotReticulum.Core;

namespace DotReticulum.Applications.Tests;

/// <summary>
/// Independently generated by GenerateParity7RnidVectors.py using RNS 1.5.7 at
/// a29bfb51c468945c96a1ee22cae0114e993e2391. Fixture records the actual rnid.py SHA-256.
/// All test keys are intentionally public, disposable synthetic bytes, never operational keys.
/// </summary>
[Trait("Category", "Unit")]
public sealed class Parity7RnidTests : IDisposable
{
    private readonly string root = Path.Combine(FindRepository(), "TestResults", "rnid-unit-" + Guid.NewGuid().ToString("N"));
    private readonly JsonDocument fixture = JsonDocument.Parse(File.ReadAllText(Path.Combine(FindRepository(),
        "tests", "DotReticulum.Applications.Tests", "Fixtures", "parity7-rnid.json")));
    private JsonElement Data => fixture.RootElement;
    private static byte[] PublicTestPrivate => Enumerable.Range(0, 64).Select(i => (byte)i).ToArray();

    public Parity7RnidTests() => Directory.CreateDirectory(root);

    [Theory]
    [InlineData("hex")]
    [InlineData("base32")]
    [InlineData("base64")]
    [InlineData("base256")]
    public void CurrentEmbeddedAndWrappedSignaturesMatchPinnedReference(string format)
    {
        using var identity = Identity.FromPrivateKey(PublicTestPrivate);
        var message = Convert.FromHexString(Data.GetProperty("message").GetString()!);
        var bytes = RngitSignatures.CreateRsg(identity, message, embed: true);
        var wrapped = RnidEncoding.Wrap(RnidEncoding.Encode(bytes, format));
        Assert.Equal(Data.GetProperty("wrapped").GetProperty(format).GetString(), wrapped);
        Assert.Equal(bytes, RnidEncoding.DecodeSignature(Encoding.UTF8.GetBytes(wrapped)));
    }

    [Fact]
    public void AllBase256CodepointsAndPublicKeyEncodingsMatchReference()
    {
        var bytes = Enumerable.Range(0, 256).Select(i => (byte)i).ToArray();
        Assert.Equal(Data.GetProperty("base256_alphabet").GetString(), RnidEncoding.Encode(bytes, "base256"));
        Assert.Equal(bytes, RnidEncoding.Decode(Data.GetProperty("base256_alphabet").GetString()!, "base256"));
        var pub = Convert.FromHexString(Data.GetProperty("public").GetString()!);
        foreach (var format in new[] { "base32", "base64" })
        {
            Assert.Equal(Data.GetProperty(format).GetString(), RnidEncoding.Encode(pub, format));
            Assert.Equal(pub, RnidEncoding.Decode(Data.GetProperty(format).GetString()!, format));
        }

    }

    [Fact]
    public async Task CliFormattingAndExitStatusMatchExecutedPinnedEntrypoint()
    {
        foreach (var example in Data.GetProperty("cli_cases").EnumerateArray())
        {
            var actual = await Run(example.GetProperty("arguments").EnumerateArray().Select(v => v.GetString()!).ToArray());
            Assert.Equal(example.GetProperty("code").GetInt32(), actual.Code);
            Assert.Equal(example.GetProperty("stdout").GetString(), actual.Output.Replace("\r\n", "\n", StringComparison.Ordinal));
            Assert.Equal(example.GetProperty("stderr").GetString(), actual.Error.Replace("\r\n", "\n", StringComparison.Ordinal));
        }

    }

    [Fact]
    public async Task AttachedShortOptionsAndRepeatedVerbosityPreserveIdentityFormatting()
    {
        var result = await Run(["-m" + Data.GetProperty("public").GetString(), "-x", "-vv", "-q", "--quiet"]);
        Assert.Equal(0, result.Code);
        Assert.Contains("Public Identity Keys  : " + Data.GetProperty("public").GetString(), result.Output);
    }

    [Fact]
    public async Task AmbiguousLongOptionsAndMalformedClustersFailLikePinnedArgumentParser()
    {
        foreach (var example in Data.GetProperty("parser_errors").EnumerateArray())
        {
            var result = await Run(example.GetProperty("arguments").EnumerateArray().Select(a => a.GetString()!).ToArray());
            Assert.Equal(example.GetProperty("code").GetInt32(), result.Code);
            Assert.NotEmpty(result.Output + result.Error);
        }
    }

    [Theory]
    [InlineData("public")]
    [InlineData("base32")]
    [InlineData("base64")]
    public async Task PublicImportExportPersistsAndCannotSign(string encoding)
    {
        var path = Path.Combine(root, encoding);
        var value = Data.GetProperty(encoding).GetString()!;
        var result = await Run(["-m", value, "-x", "-w", path]);
        Assert.Equal(0, result.Code);
        Assert.Contains("Public Identity Keys  : " + Data.GetProperty("public").GetString(), result.Output);
        Assert.Equal(Convert.FromHexString(Data.GetProperty("public").GetString()!), await File.ReadAllBytesAsync(path + ".pub"));
        var data = Path.Combine(root, "data");
        await File.WriteAllTextAsync(data, "message");
        Assert.Equal(4, (await Run(["-m", path + ".pub", "-s", data])).Code);
    }

    [Fact]
    public async Task PrivateImportIsExplicitAndPrintHidesPrivateKey()
    {
        var key = Convert.ToHexStringLower(PublicTestPrivate);
        var path = Path.Combine(root, "identity.rid");
        var imported = await Run(["-M", key, "-X", "-w", path, "-B"]);
        Assert.Equal(0, imported.Code);
        Assert.Equal(PublicTestPrivate, await File.ReadAllBytesAsync(path));
        var printed = await Run(["-i", path, "-p"]);
        Assert.Equal(0, printed.Code);
        Assert.Contains("Private Key   : Hidden", printed.Output);
        Assert.DoesNotContain(key, printed.Output);
        Assert.Contains(key, (await Run(["-i", path, "-p", "-P"])).Output);
        Assert.Equal(11, (await Run(["-M", key, "-X", "-w", path])).Code);
        Assert.Equal(0, (await Run(["-M", key, "-X", "-w", path, "-f"])).Code);
    }

    [Fact]
    public async Task LegacyGenerateAndShowRetainOutputAndNeverOverwriteByDefault()
    {
        var path = Path.Combine(root, "identity");
        var generated = await Run(["--generate", path]);
        Assert.Equal(0, generated.Code);
        Assert.Contains("Identity hash: ", generated.Output);
        Assert.Contains("Public key:    ", generated.Output);
        var original = await File.ReadAllBytesAsync(path);
        var refused = await Run(["--generate", path]);
        Assert.Equal(1, refused.Code);
        Assert.Empty(refused.Output);
        Assert.NotEmpty(refused.Error);
        Assert.Equal(original, await File.ReadAllBytesAsync(path));
        Assert.Equal(generated.Output, (await Run(["--show", path])).Output);
    }

    [Fact]
    public async Task CurrentAndLegacySignaturesVerifyAndTamperingFails()
    {
        var target = Path.Combine(root, "data");
        var message = Convert.FromHexString(Data.GetProperty("message").GetString()!);
        await File.WriteAllBytesAsync(target, message);
        var key = Convert.ToHexStringLower(PublicTestPrivate);
        Assert.Equal(0, (await Run(["-M", key, "-s", target])).Code);
        Assert.Equal(Convert.FromHexString(Data.GetProperty("rsg").GetString()!), await File.ReadAllBytesAsync(target + ".rsg"));
        Assert.Equal(0, (await Run(["-V", target])).Code);
        Assert.Equal(11, (await Run(["-M", key, "-s", target])).Code);
        Assert.Equal(0, (await Run(["-M", key, "-s", target, "--raw", "-f"])).Code);
        Assert.Equal(Convert.FromHexString(Data.GetProperty("raw").GetString()!), await File.ReadAllBytesAsync(target + ".rsg"));
        Assert.Equal(2, (await Run(["-V", target])).Code);
        Assert.Equal(0, (await Run(["-m", Data.GetProperty("public").GetString()!, "-V", target])).Code);
        await File.AppendAllTextAsync(target, "tampered");
        Assert.Equal(10, (await Run(["-m", Data.GetProperty("public").GetString()!, "-V", target])).Code);
    }

    [Fact]
    public async Task ExplicitIdentitySelectsTrustedKeyInsteadOfUntrustedEnvelopeKeyLikeReference()
    {
        var target = Path.Combine(root, "explicit-identity");
        await File.WriteAllBytesAsync(target, Convert.FromHexString(Data.GetProperty("message").GetString()!));
        await File.WriteAllBytesAsync(target + ".rsg", Convert.FromHexString(Data.GetProperty("explicit_identity_override_rsg").GetString()!));
        Assert.True(Data.GetProperty("explicit_identity_override_valid").GetBoolean());
        Assert.Equal(10, (await Run(["-V", target])).Code);
        Assert.Equal(0, (await Run(["-m", Data.GetProperty("public").GetString()!, "-V", target])).Code);
    }

    [Fact]
    public async Task RsmMetadataAndExpectedSignerAreAuthenticatedBeforeDisplay()
    {
        var path = Path.Combine(root, "message.rsm");
        await File.WriteAllBytesAsync(path, Convert.FromHexString(Data.GetProperty("rsm").GetString()!));
        var result = await Run(["-V", path, "--meta"]);
        Assert.Equal(0, result.Code);
        Assert.Contains("s  title=Example", result.Output);
        Assert.Contains("s    value=yes", result.Output);
        Assert.Contains("Parity 7 signed message — λ", result.Output);
        Assert.Equal(10, (await Run(["-i", new string('a', 32), "-N", "-V", path])).Code);
        var tampered = await File.ReadAllBytesAsync(path);
        tampered[0] ^= 1;
        await File.WriteAllBytesAsync(path, tampered);
        var rejected = await Run(["-V", path, "--meta"]);
        Assert.Equal(10, rejected.Code);
        Assert.DoesNotContain("title=Example", rejected.Output);
    }

    [Fact]
    public async Task RecursiveMultipleFilesAndMissingPathsFailWithoutPretendingSuccess()
    {
        var first = Path.Combine(root, "first");
        var second = Path.Combine(root, "second");
        await File.WriteAllTextAsync(first, "one");
        await File.WriteAllTextAsync(second, "two");
        Assert.Equal(0, (await Run(["-M", Convert.ToHexStringLower(PublicTestPrivate), "-s", first, second])).Code);
        Assert.Equal(0, (await Run(["-V", first, second])).Code);
        File.Delete(second);
        Assert.Equal(6, (await Run(["-V", first, second])).Code);
    }

    [Fact]
    public async Task IndependentReferenceEncryptedFileDecryptsAndWrongKeyFails()
    {
        var path = Path.Combine(root, "encrypted.rfe");
        var output = Path.Combine(root, "plaintext");
        await File.WriteAllBytesAsync(path, Convert.FromHexString(Data.GetProperty("encrypted").GetString()!));
        Assert.Equal(0, (await Run(["-M", Convert.ToHexStringLower(PublicTestPrivate), "-d", path, "-w", output])).Code);
        Assert.Equal(Convert.FromHexString(Data.GetProperty("message").GetString()!), await File.ReadAllBytesAsync(output));
        Assert.Equal(12, (await Run(["-M", Convert.ToHexStringLower(PublicTestPrivate.Reverse().ToArray()), "-d", path, "-w", output, "-f"])).Code);
        Assert.Equal(7, (await Run(["-M", Convert.ToHexStringLower(PublicTestPrivate), "-d", output])).Code);
    }

    [Fact]
    public async Task EncryptionCrossesReferenceChunkBoundaryAndRejectsOverwrite()
    {
        var path = Path.Combine(root, "large");
        var data = new byte[RnidApp.EncryptionChunkBytes + 257];
        RandomNumberGenerator.Fill(data);
        await File.WriteAllBytesAsync(path, data);
        var key = Convert.ToHexStringLower(PublicTestPrivate);
        Assert.Equal(0, (await Run(["-M", key, "-e", path])).Code);
        Assert.Equal(11, (await Run(["-M", key, "-e", path])).Code);
        Assert.Equal(0, (await Run(["-M", key, "-d", path + ".rfe", "-w", path + ".out"])).Code);
        Assert.Equal(data, await File.ReadAllBytesAsync(path + ".out"));
    }

    [Fact]
    public async Task StdinRsmAndRfeUseBinaryStdoutWithoutLogPollution()
    {
        var message = "stdin λ message"u8.ToArray();
        var key = Convert.ToHexStringLower(PublicTestPrivate);
        var signed = await Run(["-M", key, "-S", "-I", "-O"], message);
        Assert.Equal(0, signed.Code);
        Assert.Empty(signed.Output);
        Assert.Equal(0, (await Run(["-V", "-", "-I"], signed.Binary)).Code);
        var encrypted = await Run(["-M", key, "-e", "-I", "-O"], message);
        Assert.Equal(0, encrypted.Code);
        var decrypted = await Run(["-M", key, "-d", "-I", "-O"], encrypted.Binary);
        Assert.Equal(0, decrypted.Code);
        Assert.Equal(message, decrypted.Binary);
    }

    [Fact]
    public async Task ExplicitEditorAuthorizationIsRequiredAndNoFilesAreLeftBehind()
    {
        var before = Directory.GetDirectories(Directory.GetCurrentDirectory(), ".rnid-editor-*");
        var result = await Run(["-M", Convert.ToHexStringLower(PublicTestPrivate), "-S", "-b"]);
        Assert.Equal(252, result.Code);
        Assert.Contains("--allow-editor", result.Output);
        Assert.Equal(before, Directory.GetDirectories(Directory.GetCurrentDirectory(), ".rnid-editor-*"));
        var failed = await Run(["-M", Convert.ToHexStringLower(PublicTestPrivate), "-S", "-b", "--allow-editor", "--editor", Path.Combine(root, "missing-editor")]);
        Assert.Equal(252, failed.Code);
        Assert.Equal(before, Directory.GetDirectories(Directory.GetCurrentDirectory(), ".rnid-editor-*"));
    }

    [Fact]
    public void MetadataMatchesReferenceAndSpecConvertsValuesWithoutOverwritingSignerFields()
    {
        var parsed = RnidMetadata.Parse("title = Example\ncount = 3\n[nested]\nvalue = yes\n");
        Assert.Equal("Example", parsed["title"]);
        Assert.Equal("3", parsed["count"]);
        var validated = RnidMetadata.Parse("number=3\nflag=yes\nitems=a, b\n", "number=\"integer(1, 5)\"\nflag=boolean()\nitems=string_list(min=2)\n");
        Assert.Equal(3L, validated["number"]);
        Assert.Equal(true, validated["flag"]);
        Assert.Throws<FormatException>(() => RnidMetadata.Parse("number=8", "number=\"integer(1, 5)\""));
        Assert.Throws<FormatException>(() => RnidMetadata.Parse("key=a\nkey=b"));
        using var identity = Identity.FromPrivateKey(PublicTestPrivate);
        Assert.Equal(Convert.FromHexString(Data.GetProperty("rsm").GetString()!), RngitSignatures.CreateRsg(identity,
            Convert.FromHexString(Data.GetProperty("message").GetString()!), true, parsed));
    }

    [Fact]
    public void MetadataInterpolationDefaultsAndEveryBuiltinListTypeMatchPinnedReference()
    {
        foreach (var example in Data.GetProperty("metadata_cases").EnumerateArray())
        {
            var actual = RnidMetadata.Parse(example.GetProperty("text").GetString()!,
                example.GetProperty("spec").ValueKind == JsonValueKind.Null ? null : example.GetProperty("spec").GetString());
            Assert.Equal(Normalize(example.GetProperty("result")), Normalize(JsonSerializer.SerializeToElement(actual)));
        }
        Assert.Throws<FormatException>(() => RnidMetadata.Parse("a=%(b)s\nb=%(a)s"));
        Assert.Throws<FormatException>(() => RnidMetadata.Parse("a=%(missing)s"));
    }

    private static string Normalize(JsonElement element) => element.ValueKind switch
    {
        JsonValueKind.Object => "{" + string.Join(",", element.EnumerateObject().OrderBy(p => p.Name, StringComparer.Ordinal).Select(p => p.Name + ":" + Normalize(p.Value))) + "}",
        JsonValueKind.Array => "[" + string.Join(",", element.EnumerateArray().Select(Normalize)) + "]",
        _ => element.GetRawText()
    };

    [Theory]
    [InlineData("-i", "missing", "-p", 2)]
    [InlineData("-m", "invalid", "-p", 8)]
    [InlineData("-t", "NaN", "-p", 2)]
    [InlineData("-t", "-1", "-p", 2)]
    [InlineData("-b", "-B", "-p", 1)]
    [InlineData("-s", "-e", "-p", 1)]
    public async Task MalformedArgumentsHaveSpecificNonzeroExitCodes(string first, string second, string third, int expected)
        => Assert.Equal(expected, (await Run([first, second, third])).Code);

    [Fact]
    public async Task HashCanUseUncachedIdentityHashAndCancellationSettles()
    {
        var result = await Run(["-i", Data.GetProperty("hash").GetString()!, "-N", "-H", "rns.id"]);
        Assert.Equal(0, result.Code);
        Assert.Contains(Data.GetProperty("destination").GetString()!, result.Output);
        using var stop = new CancellationTokenSource();
        stop.Cancel();
        var cancelled = await Run(["-M", Convert.ToHexStringLower(PublicTestPrivate), "-p"], token: stop.Token);
        Assert.Equal(255, cancelled.Code);
    }

    [Fact]
    public async Task OversizedAndMalformedInputsFailBeforeWritingOutputs()
    {
        var badKey = Path.Combine(root, "bad-key");
        await File.WriteAllBytesAsync(badKey, new byte[65]);
        Assert.Equal(8, (await Run(["-M", badKey, "-p"])).Code);
        var target = Path.Combine(root, "oversized-raw");
        await using (var stream = File.Create(target)) stream.SetLength(RngitSignatures.MaximumMessageBytes + 1L);
        Assert.Equal(252, (await Run(["-M", Convert.ToHexStringLower(PublicTestPrivate), "-s", target, "--raw"])).Code);
        Assert.False(File.Exists(target + ".rsg"));
        var malformed = Path.Combine(root, "malformed.rsm");
        await File.WriteAllBytesAsync(malformed, "not an rsg"u8.ToArray());
        Assert.Equal(10, (await Run(["-V", malformed])).Code);
        Assert.Throws<FormatException>(() => RnidEncoding.Decode("!", "base256"));
        Assert.Throws<FormatException>(() => RnidEncoding.Decode("a=======", "base32"));
        Assert.Throws<FormatException>(() => RnidMetadata.Parse(new string('x', 1024 * 1024 + 1)));
    }

    [Fact]
    public async Task EmptyFilesRoundTripButEmptyEmbeddedMessagesAreRejected()
    {
        var target = Path.Combine(root, "empty");
        await File.WriteAllBytesAsync(target, []);
        var key = Convert.ToHexStringLower(PublicTestPrivate);
        Assert.Equal(0, (await Run(["-M", key, "-e", target])).Code);
        Assert.Empty(await File.ReadAllBytesAsync(target + ".rfe"));
        Assert.Equal(0, (await Run(["-M", key, "-d", target + ".rfe", "-w", target + ".out"])).Code);
        Assert.Empty(await File.ReadAllBytesAsync(target + ".out"));
        Assert.Equal(250, (await Run(["-M", key, "-S", "", "-b"])).Code);
    }

    private async Task<(int Code, string Output, string Error, byte[] Binary)> Run(string[] args, byte[]? bytes = null,
        CancellationToken token = default)
    {
        using var input = new MemoryStream(bytes ?? []);
        using var binary = new MemoryStream();
        using var output = new StringWriter();
        using var error = new StringWriter();
        var code = await RnidApp.RunAsync(args, input, binary, output, error, token);
        return (code, output.ToString(), error.ToString(), binary.ToArray());
    }

    private static string FindRepository()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null && !File.Exists(Path.Combine(directory.FullName, "DotReticulum.slnx"))) directory = directory.Parent;
        return directory?.FullName ?? throw new DirectoryNotFoundException("Repository root not found.");
    }

    public void Dispose()
    {
        fixture.Dispose();
        Directory.Delete(root, recursive: true);
    }
}
